'use strict';

const { SYMBOL_COMMANDS } = require('./lexer');
const LARGE_GLYPHS = new Map([['\\sum', ['\\--', ' > ', '/--']], ['\\prod', ['___', '| |', '| |']], ['\\int', [' /', ' |', '/ ']]]);
const SYMBOL_TYPES = new Map();
for (const [characters, type] of [['+-*', 'binary'], ['=<>:', 'relation'], ['([', 'open'], [')]!', 'close'], [',;', 'punctuation'], ['/.|\'', 'ordinary']]) {
  for (const character of characters) SYMBOL_TYPES.set(character, type);
}

class Box {
  constructor(width, height, baseline, description) {
    this.width = width; this.height = height; this.baseline = baseline; this.description = description;
    this.children = []; this.strings = [];
  }
  add(box, x, y, role = '') { this.children.push({ box, x, y, role }); return this; }
  draw(text, x = 0, y = 0) { this.strings.push({ text, x, y }); return this; }
}

function atomType(node) {
  if (node.atom === 'symbol') return SYMBOL_TYPES.get(node.value);
  if (node.atom === 'command') return SYMBOL_COMMANDS.get(node.value).type;
  return 'ordinary';
}

function atomDisplay(node, references) {
  if (node.atom === 'reference') return references.has(node.value) ? references.get(node.value) : '(??)';
  if (node.atom === 'command') return SYMBOL_COMMANDS.get(node.value).display;
  return node.value;
}

function delimiterGlyph(delimiter, height) {
  if (delimiter === '.') return { width: 0, lines: [] };
  if (height === 1) return { width: 1, lines: [delimiter.length === 1 ? delimiter : delimiter[1]] };
  if (delimiter === '[' || delimiter === ']' || delimiter === '|') return { width: 1, lines: Array(height).fill(delimiter) };
  const left = delimiter === '(' || delimiter === '\\{', lines = Array(height).fill('|');
  lines[0] = left ? '/' : '\\'; lines[height - 1] = left ? '\\' : '/';
  if (height >= 3 && (delimiter === '\\{' || delimiter === '\\}')) lines[Math.floor((height - 1) / 2)] = left ? '<' : '>';
  return { width: 1, lines };
}

const center = (box, width) => Math.floor((width - box.width) / 2);
module.exports = { Box, LARGE_GLYPHS, atomType, atomDisplay, delimiterGlyph, center };

'use strict';

function entries(roots) {
  const result = [];
  const visit = (placement, x, y, level) => {
    x += placement.x; y += placement.y;
    result.push({ box: placement.box, x, y, level, role: placement.role || '' });
    for (const child of placement.box.children) visit(child, x, y, level + 1);
  };
  for (const root of roots) visit(root, 0, 0, 0);
  return result;
}

function draw(placements, width, height) {
  const grid = Array.from({ length: height }, () => Array(width).fill(' '));
  for (const entry of placements) for (const string of entry.box.strings) {
    for (let i = 0; i < string.text.length; i++) {
      if (string.text[i] !== ' ') grid[entry.y + string.y][entry.x + string.x + i] = string.text[i];
    }
  }
  return grid.map(row => row.join('').replace(/ +$/, ''));
}

function boxLines(placements) {
  return placements.map(({ box, x, y, level, role }) => ' '.repeat(2 * level) + role + box.description
    + ` x=${x} y=${y} w=${box.width} h=${box.height} b=${box.baseline}`);
}

module.exports = { entries, draw, boxLines };

'use strict';

const { GREEK } = require('./lexer');
const { Box, atomType } = require('./boxes');

function types(node) {
  if (node.kind === 'atom') { const type = atomType(node); return [type, type]; }
  if (node.kind === 'delim') return ['open', 'close'];
  if (node.kind === 'script' || node.kind === 'overset' || node.kind === 'underset') return types(node.base);
  return ['ordinary', 'ordinary'];
}

function word(node) {
  if (node.kind === 'script') return word(node.base);
  return node.kind === 'atom' && node.atom === 'command' && (GREEK.has(node.value.slice(1)) || node.value === '\\infty');
}

function alphanumeric(node) {
  if (word(node)) return true;
  if (node.kind === 'atom') return node.atom === 'identifier' || node.atom === 'number';
  if (node.kind === 'script') return alphanumeric(node.base);
  return node.kind === 'accent' && ['overline', 'hat', 'vec', 'dot', 'tilde'].includes(node.name) && alphanumeric(node.body);
}

const TYPE_ORDER = ['ordinary', 'operator', 'binary', 'relation', 'open', 'close', 'punctuation'];
const SPACE_TABLE = [
  [0, 1, 'B', 'R', 0, 0, 0], [1, 1, null, 'R', 0, 0, 0],
  ['B', 'B', null, null, 'B', null, null], ['R', 'R', null, 0, 'R', 0, 0],
  [0, 0, null, 0, 0, 0, 0], [0, 1, 'B', 'R', 0, 0, 0], ['P', 'P', null, 'P', 'P', 'P', 'P'],
];

function spacing(elements, style, params) {
  const converted = elements.map(types), gaps = [];
  for (let i = 0; i < converted.length; i++) {
    if (converted[i][0] === 'binary' && (i === 0 || ['binary', 'operator', 'relation', 'open', 'punctuation'].includes(converted[i - 1][1]))) {
      converted[i] = ['ordinary', 'ordinary'];
    }
    if (i > 0 && ['relation', 'close', 'punctuation'].includes(converted[i][0]) && converted[i - 1][1] === 'binary') {
      converted[i - 1] = ['ordinary', 'ordinary'];
    }
  }
  if (converted.length && converted[converted.length - 1][1] === 'binary') converted[converted.length - 1] = ['ordinary', 'ordinary'];
  const widths = { B: style === 'script' ? 0 : params.bin_space, R: style === 'script' ? 0 : params.rel_space, P: style === 'script' ? 0 : params.punct_space };
  for (let i = 0; i + 1 < elements.length; i++) {
    if (alphanumeric(elements[i]) && alphanumeric(elements[i + 1]) && (word(elements[i]) || word(elements[i + 1]))) gaps.push(1);
    else {
      const value = SPACE_TABLE[TYPE_ORDER.indexOf(converted[i][1])][TYPE_ORDER.indexOf(converted[i + 1][0])];
      gaps.push(typeof value === 'number' ? value : widths[value]);
    }
  }
  return { types: converted, gaps };
}

function rowBox(elements, gaps, description = 'row', roles = []) {
  const ascent = Math.max(0, ...elements.map(box => box.baseline));
  const descent = Math.max(0, ...elements.map(box => box.height - 1 - box.baseline));
  const result = new Box(0, ascent + descent + 1, ascent, description);
  elements.forEach((box, i) => {
    result.add(box, result.width, ascent - box.baseline, roles[i] || '');
    result.width += box.width;
    if (i < elements.length - 1) result.width += gaps[i];
  });
  return result;
}

module.exports = { types, word, alphanumeric, spacing, rowBox };

'use strict';

class FormulaError extends Error {
  constructor(column, message) { super(message); this.column = column; }
}

const GREEK = new Set(('alpha beta gamma delta epsilon zeta eta theta iota kappa lambda mu nu xi pi rho sigma tau upsilon phi chi psi omega '
  + 'Gamma Delta Theta Lambda Xi Pi Sigma Upsilon Phi Psi Omega').split(' '));
const SYMBOL_COMMANDS = new Map();
for (const name of GREEK) SYMBOL_COMMANDS.set('\\' + name, { display: name, type: 'ordinary' });
for (const [name, display] of [['cdot', '*'], ['times', 'x'], ['pm', '+-'], ['mp', '-+']]) {
  SYMBOL_COMMANDS.set('\\' + name, { display, type: 'binary' });
}
for (const [name, display] of [['leq', '<='], ['geq', '>='], ['neq', '!='], ['approx', '~='], ['to', '->']]) {
  SYMBOL_COMMANDS.set('\\' + name, { display, type: 'relation' });
}
for (const [name, display] of [['infty', 'oo'], ['ldots', '...'], ['cdots', '...'], ['quad', '  '], [',', ' ']]) {
  SYMBOL_COMMANDS.set('\\' + name, { display, type: 'ordinary' });
}
SYMBOL_COMMANDS.set('\\{', { display: '{', type: 'open' });
SYMBOL_COMMANDS.set('\\}', { display: '}', type: 'close' });
for (const name of 'sin cos tan log ln exp det lim max min sum prod int'.split(' ')) {
  SYMBOL_COMMANDS.set('\\' + name, { display: name, type: 'operator' });
}
const COMMAND_NAMES = new Set(Array.from(SYMBOL_COMMANDS.keys()).map(value => value.slice(1)).filter(value => /^[A-Za-z]+$/.test(value)));
const ACCENTS = new Set('overline hat vec dot tilde overbrace underbrace'.split(' '));
const RAW_COMMANDS = new Set(['text', 'begin', 'end', 'tag', 'label', 'eqref']);
const ENVIRONMENTS = new Set(['matrix', 'pmatrix', 'bmatrix', 'vmatrix', 'cases']);
const CONSTRUCTS = new Set(['frac', 'binom', 'overset', 'underset', 'sqrt', 'left', 'right']);
const letter = character => character !== undefined && /[A-Za-z]/.test(character);
const digit = character => character !== undefined && character >= '0' && character <= '9';

function tokenize(line) {
  const tokens = [];
  let index = 0;
  const append = (kind, value, column) => tokens.push({ kind, value, column });
  while (index < line.length) {
    const start = index, character = line[index], column = start + 1;
    if (character === ' ') { index++; continue; }
    if (letter(character)) {
      while (letter(line[index])) index++;
      append('identifier', line.slice(start, index), column); continue;
    }
    if (digit(character)) {
      while (digit(line[index])) index++;
      if (line[index] === '.' && digit(line[index + 1])) { index++; while (digit(line[index])) index++; }
      append('number', line.slice(start, index), column); continue;
    }
    if ('+-*/=<>:()[],;.!|\''.includes(character)) { append('symbol', character, column); index++; continue; }
    if ('{}^_&'.includes(character)) { append(character, character, column); index++; continue; }
    if (character !== '\\') throw new FormulaError(column, 'invalid character ' + character);
    index++;
    if (line[index] === '\\') { append('newline', '\\\\', column); index++; continue; }
    if (['{', '}', ','].includes(line[index])) { append('command', '\\' + line[index++], column); continue; }
    const nameStart = index;
    while (letter(line[index])) index++;
    const name = line.slice(nameStart, index);
    if (name === '') throw new FormulaError(column, 'invalid command');
    if (RAW_COMMANDS.has(name)) {
      while (line[index] === ' ') index++;
      if (line[index] !== '{') throw new FormulaError(index + 1, 'expected {');
      const end = line.indexOf('}', index + 1);
      if (end < 0) throw new FormulaError(column, 'unterminated argument');
      const argument = line.slice(index + 1, end); index = end + 1;
      if ((name === 'begin' || name === 'end') && !ENVIRONMENTS.has(argument)) {
        throw new FormulaError(column, `unknown environment "${argument}"`);
      }
      append(name, argument, column);
    } else if (SYMBOL_COMMANDS.has('\\' + name)) append('command', '\\' + name, column);
    else if (ACCENTS.has(name)) append('accent', name, column);
    else if (CONSTRUCTS.has(name)) append(name, name, column);
    else throw new FormulaError(column, 'unknown command \\' + name);
  }
  append('eof', '', line.length + 1);
  return tokens;
}

module.exports = { FormulaError, GREEK, SYMBOL_COMMANDS, COMMAND_NAMES, tokenize };

'use strict';

const fs = require('node:fs');
const { FormulaError, COMMAND_NAMES, tokenize } = require('./lexer');
const { Parser } = require('./parser');
const { Box, LARGE_GLYPHS, atomDisplay, delimiterGlyph, center } = require('./boxes');
const { spacing, rowBox } = require('./layout');
const { entries, draw, boxLines } = require('./canvas');

function inputLines(name) {
  return fs.readFileSync('input/' + name, 'ascii').slice(0, -1).split('\n');
}

function parseFormulas(lines) {
  return lines.map((source, index) => {
    const formula = { number: index + 1, source, warnings: [] };
    try {
      formula.tokens = tokenize(source);
      Object.assign(formula, new Parser(formula.tokens).parse());
    } catch (error) {
      if (!(error instanceof FormulaError)) throw error;
      formula.error = { column: error.column, message: error.message };
    }
    return formula;
  });
}

function equationReferences(formulas) {
  const references = new Map();
  let counter = 0;
  for (const formula of formulas) {
    if (formula.error) continue;
    if (formula.tag !== null) formula.tagString = '(' + formula.tag.value + ')';
    else if (formula.label !== null) formula.tagString = '(' + (++counter) + ')';
    else formula.tagString = null;
  }
  for (const formula of formulas) {
    if (formula.error || formula.label === null) continue;
    const { value, column } = formula.label;
    if (references.has(value)) formula.warnings.push({ column, message: `duplicate label "${value}"` });
    else references.set(value, formula.tagString);
  }
  return references;
}

function drawGlyph(box, glyph, x) {
  glyph.lines.forEach((line, y) => box.draw(line, x, y));
}

class Typesetter {
  constructor(params, references) { this.params = params; this.references = references; }

  atom(node, style) {
    const kind = node.atom === 'text' ? 'text' : node.atom === 'reference' ? 'eqref' : 'atom';
    const description = `${kind} "${node.value}"`;
    if (node.atom === 'command' && style === 'normal' && LARGE_GLYPHS.has(node.value)) {
      const glyph = LARGE_GLYPHS.get(node.value), result = new Box(glyph[0].length, 3, 1, description);
      glyph.forEach((line, y) => result.draw(line, 0, y));
      return result;
    }
    const display = atomDisplay(node, this.references);
    return new Box(display.length, 1, 0, description).draw(display);
  }

  scripts(node, style) {
    const base = this.box(node.base, style);
    const sub = node.sub === null ? null : this.box(node.sub, 'script');
    const sup = node.sup === null ? null : this.box(node.sup, 'script');
    const subWidth = sub === null ? 0 : sub.width, supWidth = sup === null ? 0 : sup.width;
    const subHeight = sub === null ? 0 : sub.height, supHeight = sup === null ? 0 : sup.height;
    const stacked = style === 'normal' && ((node.base.kind === 'atom' && node.base.atom === 'command'
      && ['\\sum', '\\prod', '\\lim', '\\max', '\\min'].includes(node.base.value))
      || (node.base.kind === 'accent' && ['overbrace', 'underbrace'].includes(node.base.name)));
    if (stacked) {
      const width = Math.max(base.width, subWidth, supWidth);
      const result = new Box(width, supHeight + base.height + subHeight, supHeight + base.baseline, 'limits');
      result.add(base, center(base, width), supHeight, 'base: ');
      if (sub !== null) result.add(sub, center(sub, width), supHeight + base.height, 'sub: ');
      if (sup !== null) result.add(sup, center(sup, width), 0, 'sup: ');
      return result;
    }
    const supTop = (base.baseline === 0 ? -1 : 0) - supHeight + 1;
    const subTop = base.height - 1 - base.baseline === 0 ? base.height : base.height - 1;
    const top = sup === null ? 0 : Math.min(0, supTop);
    const bottom = sub === null ? base.height - 1 : Math.max(base.height - 1, subTop + subHeight - 1);
    const result = new Box(base.width + Math.max(subWidth, supWidth), bottom - top + 1, base.baseline - top, 'scripts');
    result.add(base, 0, -top, 'base: ');
    if (sub !== null) result.add(sub, base.width, subTop - top, 'sub: ');
    if (sup !== null) result.add(sup, base.width, supTop - top, 'sup: ');
    return result;
  }

  fraction(node, style) {
    if (style === 'script') {
      const parenthesized = child => child.kind === 'row' || child.kind === 'frac'
        ? { kind: 'delim', left: '(', right: ')', body: child } : child;
      const numerator = this.box(parenthesized(node.first), style), denominator = this.box(parenthesized(node.second), style);
      const slash = new Box(1, 1, 0, 'atom "/"').draw('/');
      return rowBox([numerator, slash, denominator], [0, 0], 'slash', ['num: ', '', 'den: ']);
    }
    const numerator = this.box(node.first, style), denominator = this.box(node.second, style);
    const width = Math.max(numerator.width, denominator.width) + 2;
    const result = new Box(width, numerator.height + 1 + denominator.height, numerator.height, 'frac');
    result.add(numerator, center(numerator, width), 0, 'num: ');
    result.add(denominator, center(denominator, width), numerator.height + 1, 'den: ');
    return result.draw('-'.repeat(width), 0, numerator.height);
  }

  binomial(node, style) {
    const upper = this.box(node.first, style), lower = this.box(node.second, style);
    const width = Math.max(upper.width, lower.width), height = upper.height + 1 + lower.height;
    const result = new Box(width + 2, height, upper.height, 'binom');
    result.add(upper, center(upper, width) + 1, 0, 'upper: ');
    result.add(lower, center(lower, width) + 1, upper.height + 1, 'lower: ');
    drawGlyph(result, delimiterGlyph('(', height), 0);
    drawGlyph(result, delimiterGlyph(')', height), width + 1);
    return result;
  }

  placed(node, style) {
    const placed = this.box(node.placed, 'script'), base = this.box(node.base, style);
    const width = Math.max(placed.width, base.width), over = node.kind === 'overset';
    const result = new Box(width, placed.height + base.height, base.baseline + (over ? placed.height : 0), node.kind);
    if (over) {
      result.add(placed, center(placed, width), 0, 'over: ');
      result.add(base, center(base, width), placed.height, 'base: ');
    } else {
      result.add(base, center(base, width), 0, 'base: ');
      result.add(placed, center(placed, width), base.height, 'under: ');
    }
    return result;
  }

  radical(node, style) {
    const body = this.box(node.body, style), index = node.kind === 'root' ? this.box(node.index, 'script') : null;
    const height = body.height, extra = index === null ? 0 : Math.max(0, index.width - 1);
    const top = index === null ? 0 : Math.max(0, index.height - height);
    const result = new Box(extra + height + 1 + body.width, height + 1 + top, body.baseline + 1 + top, node.kind);
    result.draw('_'.repeat(body.width), extra + height + 1, top).draw('\\', extra, height + top);
    for (let row = 1; row <= height; row++) result.draw('/', extra + height - row + 1, row + top);
    if (index !== null) result.add(index, 0, height - index.height + top, 'index: ');
    result.add(body, extra + height + 1, 1 + top, index === null ? '' : 'body: ');
    return result;
  }

  delimited(node, style) {
    const body = this.box(node.body, style), left = delimiterGlyph(node.left, body.height), right = delimiterGlyph(node.right, body.height);
    const result = new Box(left.width + body.width + right.width, body.height, body.baseline, `delim ${node.left} ${node.right}`);
    drawGlyph(result, left, 0);
    result.add(body, left.width, 0);
    drawGlyph(result, right, left.width + body.width);
    return result;
  }

  matrix(node, style) {
    const cells = node.rows.map(row => row.map(cell => this.box(cell, style)));
    const rowCount = cells.length, columns = cells[0].length;
    const widths = Array(columns).fill(0), ascents = [], heights = [], lefts = [], tops = [];
    for (const row of cells) {
      let ascent = 0, descent = 0;
      row.forEach((cell, column) => {
        widths[column] = Math.max(widths[column], cell.width);
        ascent = Math.max(ascent, cell.baseline); descent = Math.max(descent, cell.height - 1 - cell.baseline);
      });
      ascents.push(ascent); heights.push(ascent + descent + 1);
    }
    let bodyWidth = 0, bodyHeight = 0;
    for (let column = 0; column < columns; column++) {
      lefts.push(bodyWidth); bodyWidth += widths[column];
      if (column + 1 < columns) bodyWidth += this.params.col_gap;
    }
    for (let row = 0; row < rowCount; row++) {
      tops.push(bodyHeight); bodyHeight += heights[row];
      if (row + 1 < rowCount) bodyHeight += this.params.row_gap;
    }
    const environment = node.environment, shift = environment === 'matrix' ? 0 : 2;
    const extra = environment === 'matrix' ? 0 : environment === 'cases' ? 2 : 4;
    const result = new Box(bodyWidth + extra, bodyHeight, Math.floor((bodyHeight - 1) / 2), `${environment} rows=${rowCount} cols=${columns}`);
    cells.forEach((row, i) => row.forEach((cell, j) => {
      const offset = environment === 'cases' ? 0 : center(cell, widths[j]);
      result.add(cell, shift + lefts[j] + offset, tops[i] + ascents[i] - cell.baseline, `cell ${i + 1},${j + 1}: `);
    }));
    if (environment === 'cases') drawGlyph(result, delimiterGlyph('\\{', bodyHeight), 0);
    else if (environment !== 'matrix') {
      const delimiters = { pmatrix: ['(', ')'], bmatrix: ['[', ']'], vmatrix: ['|', '|'] }[environment];
      drawGlyph(result, delimiterGlyph(delimiters[0], bodyHeight), 0);
      drawGlyph(result, delimiterGlyph(delimiters[1], bodyHeight), bodyWidth + 3);
    }
    return result;
  }

  accent(node, style) {
    const body = this.box(node.body, style), name = node.name;
    let width = body.width;
    if (['hat', 'dot', 'tilde'].includes(name)) width = Math.max(width, 1);
    else if (name === 'vec') width = Math.max(width, 2);
    else if (name === 'overbrace' || name === 'underbrace') width += 2;
    const result = new Box(width, body.height + 1, body.baseline + (name === 'underbrace' ? 0 : 1), name);
    if (name === 'underbrace') return result.add(body, 1, 0).draw('\\' + '-'.repeat(body.width) + '/', 0, body.height);
    result.add(body, name === 'overbrace' ? 1 : 0, 1);
    if (name === 'overline') result.draw('_'.repeat(width));
    else if (name === 'vec') result.draw('-'.repeat(width - 1) + '>');
    else if (name === 'overbrace') result.draw('/' + '-'.repeat(body.width) + '\\');
    else result.draw({ hat: '^', dot: '.', tilde: '~' }[name], Math.floor((width - 1) / 2), 0);
    return result;
  }

  box(node, style) {
    switch (node.kind) {
      case 'atom': return this.atom(node, style);
      case 'row': return rowBox(node.elements.map(child => this.box(child, style)), spacing(node.elements, style, this.params).gaps);
      case 'script': return this.scripts(node, style);
      case 'frac': return this.fraction(node, style);
      case 'binom': return this.binomial(node, style);
      case 'overset': case 'underset': return this.placed(node, style);
      case 'sqrt': case 'root': return this.radical(node, style);
      case 'delim': return this.delimited(node, style);
      case 'matrix': return this.matrix(node, style);
      case 'accent': return this.accent(node, style);
    }
  }
}

function buildLines(elements, boxes, types, gaps, params, pass) {
  const breaks = [], lefts = [0];
  for (let i = 1; i < elements.length; i++) {
    lefts.push(lefts[i - 1] + boxes[i - 1].width + gaps[i - 1]);
    const plusMinus = elements[i].kind === 'atom' && elements[i].atom === 'symbol'
      && ['+', '-'].includes(elements[i].value) && types[i][0] === 'binary';
    if (types[i][0] === 'relation' || (pass >= 1 && plusMinus) || (pass >= 2 && types[i - 1][1] === 'punctuation')) breaks.push(i);
  }
  breaks.push(elements.length);
  const width = (start, end) => lefts[end - 1] + boxes[end - 1].width - lefts[start];
  const lines = [];
  let start = 0, alignment = null, relationWidth = 0;
  while (start < elements.length) {
    const indent = start === 0 ? 0 : alignment === null ? params.indent
      : types[start][0] === 'relation' ? alignment : alignment + relationWidth + params.rel_space;
    const candidates = breaks.filter(end => end > start);
    let chosen = null;
    for (const end of candidates) if (indent + width(start, end) <= params.width) chosen = end;
    if (chosen === null) chosen = candidates[0];
    lines.push({ start, end: chosen, indent, width: width(start, chosen) });
    if (start === 0) {
      for (let i = 0; i < chosen; i++) if (types[i][0] === 'relation') {
        alignment = lefts[i]; relationWidth = boxes[i].width; break;
      }
    }
    start = chosen;
  }
  return lines;
}

function placeFormula(formula, typesetter, params) {
  const elements = formula.elements, boxes = elements.map(element => typesetter.box(element, 'normal'));
  const { types, gaps } = spacing(elements, 'normal', params);
  let lines;
  for (let pass = 0; pass < 3; pass++) {
    lines = buildLines(elements, boxes, types, gaps, params, pass);
    if (lines.every(line => line.indent + line.width <= params.width)) break;
  }
  const roots = [], overfull = [];
  let height = 0, width = 0;
  lines.forEach((line, index) => {
    const box = rowBox(boxes.slice(line.start, line.end), gaps.slice(line.start, line.end - 1), `line ${index + 1}`);
    roots.push({ box, x: line.indent, y: height });
    height += box.height; width = Math.max(width, line.indent + box.width);
    if (line.indent + box.width > params.width) overfull.push({ number: index + 1, width: line.indent + box.width });
  });
  if (formula.tagString !== null) {
    const tag = formula.tagString, x = params.width - tag.length, last = roots[roots.length - 1];
    const sameLine = x >= last.x + last.box.width + 2;
    const y = sameLine ? last.y + last.box.baseline : height++;
    roots.push({ box: new Box(tag.length, 1, 0, `tag "${tag}"`).draw(tag), x, y });
    width = Math.max(width, x + tag.length);
  }
  const placements = entries(roots), depth = Math.max(...placements.map(entry => entry.level)) + 1;
  return { lineCount: lines.length, width, height, placements, depth, overfull, rendered: draw(placements, width, height) };
}

function tree(node) {
  const delimiter = value => value.length === 1 ? "'" + value + "'" : value;
  switch (node.kind) {
    case 'atom':
      if (node.atom === 'symbol') return "'" + node.value + "'";
      if (node.atom === 'text') return '"' + node.value + '"';
      if (node.atom === 'reference') return `(eqref "${node.value}")`;
      return node.value;
    case 'row': return '(row' + node.elements.map(child => ' ' + tree(child)).join('') + ')';
    case 'frac': case 'binom': return `(${node.kind} ${tree(node.first)} ${tree(node.second)})`;
    case 'overset': case 'underset': return `(${node.kind} ${tree(node.placed)} ${tree(node.base)})`;
    case 'sqrt': return `(sqrt ${tree(node.body)})`;
    case 'root': return `(root ${tree(node.index)} ${tree(node.body)})`;
    case 'script':
      if (node.sub === null) return `(sup ${tree(node.base)} ${tree(node.sup)})`;
      if (node.sup === null) return `(sub ${tree(node.base)} ${tree(node.sub)})`;
      return `(subsup ${tree(node.base)} ${tree(node.sub)} ${tree(node.sup)})`;
    case 'delim': return `(delim ${delimiter(node.left)} ${delimiter(node.right)} ${tree(node.body)})`;
    case 'matrix': return '(' + node.environment + node.rows.map(row => ' [' + row.map(tree).join(' ') + ']').join('') + ')';
    case 'accent': return `(${node.name} ${tree(node.body)})`;
  }
}

function linearRow(elements, style, params, references) {
  const { gaps } = spacing(elements, style, params);
  return elements.map((child, index) => (index === 0 ? '' : ' '.repeat(gaps[index - 1])) + linear(child, style, params, references)).join('');
}

function linear(node, style, params, references) {
  const child = (value, childStyle = style) => linear(value, childStyle, params, references);
  const grouped = (value, kinds, childStyle = style) => kinds.includes(value.kind) ? '(' + child(value, childStyle) + ')' : child(value, childStyle);
  const delimiter = value => value === '.' ? '' : value.length === 1 ? value : value[1];
  switch (node.kind) {
    case 'atom': return atomDisplay(node, references);
    case 'row': return linearRow(node.elements, style, params, references);
    case 'frac': return grouped(node.first, ['row', 'frac']) + '/' + grouped(node.second, ['row', 'frac']);
    case 'binom': return `binom(${child(node.first)}, ${child(node.second)})`;
    case 'overset': case 'underset': return `${node.kind}(${child(node.placed, 'script')}, ${child(node.base)})`;
    case 'script': {
      let result = grouped(node.base, ['row', 'frac', 'script']);
      if (node.sub !== null) result += '_' + grouped(node.sub, ['row', 'frac'], 'script');
      if (node.sup !== null) result += '^' + grouped(node.sup, ['row', 'frac'], 'script');
      return result;
    }
    case 'sqrt': return `sqrt(${child(node.body)})`;
    case 'root': return `root(${child(node.index, 'script')}, ${child(node.body)})`;
    case 'delim': return delimiter(node.left) + child(node.body) + delimiter(node.right);
    case 'matrix': return node.environment + '[' + node.rows.map(row => row.map(cell => child(cell)).join(', ')).join('; ') + ']';
    case 'accent': return `${node.name}(${child(node.body)})`;
  }
}

function children(node) {
  switch (node.kind) {
    case 'atom': return [];
    case 'row': return node.elements;
    case 'frac': case 'binom': return [node.first, node.second];
    case 'overset': case 'underset': return [node.placed, node.base];
    case 'root': return [node.index, node.body];
    case 'script': return [node.base, node.sub, node.sup].filter(child => child !== null);
    case 'matrix': return node.rows.flat();
    default: return [node.body];
  }
}

function collectWarnings(formula, references) {
  for (const token of formula.tokens) {
    if (token.kind === 'identifier' && COMMAND_NAMES.has(token.value)) {
      formula.warnings.push({ column: token.column, message: `${token.value} is a command name; write \\${token.value}` });
    }
  }
  const pairs = new Map([['(', ')'], ['[', ']'], ['|', '|'], ['\\{', '\\}']]);
  const visit = node => {
    if (node.kind === 'atom' && node.atom === 'reference' && !references.has(node.value)) {
      formula.warnings.push({ column: node.column, message: `undefined reference "${node.value}"` });
    }
    if (node.kind === 'delim' && node.left !== '.' && node.right !== '.' && pairs.get(node.left) !== node.right) {
      formula.warnings.push({ column: node.rightColumn, message: `\\left${node.left} closed by \\right${node.right}` });
    }
    children(node).forEach(visit);
  };
  formula.elements.forEach(visit);
  formula.warnings.sort((a, b) => a.column - b.column);
}

function diagnostic(lines, formula, issue, warning = false) {
  lines.push(`formula ${formula.number}, column ${issue.column}: ${warning ? 'warning: ' : ''}${issue.message}`);
  lines.push('  ' + formula.source, ' '.repeat(issue.column + 1) + '^');
}

function writeReports(formulas, params, references) {
  const typesetter = new Typesetter(params, references), rendered = [], boxReport = [], trees = [], errors = [];
  const kinds = new Map();
  let valid = 0, boxCount = 0, maxDepth = 0, warningCount = 0, overfullCount = 0;
  for (const formula of formulas) {
    const heading = 'formula ' + formula.number;
    if (formula.error) {
      rendered.push(heading + '\n(error)'); boxReport.push(heading + ': error'); trees.push(heading + ': error');
      diagnostic(errors, formula, formula.error);
      continue;
    }
    valid++;
    const result = placeFormula(formula, typesetter, params);
    rendered.push([heading, ...result.rendered].join('\n'));
    boxReport.push(`${heading}: lines=${result.lineCount} width=${result.width} height=${result.height} boxes=${result.placements.length} depth=${result.depth}`);
    boxReport.push(...boxLines(result.placements));
    boxCount += result.placements.length; maxDepth = Math.max(maxDepth, result.depth);
    for (const entry of result.placements) {
      const kind = entry.box.description.split(' ')[0];
      kinds.set(kind, (kinds.get(kind) || 0) + 1);
    }
    trees.push(heading + ': ' + formula.elements.map(tree).join(' '));
    const notation = linearRow(formula.elements, 'normal', params, references).replace(/ +$/, '');
    trees.push('  linear:' + (notation === '' ? '' : ' ' + notation));
    if (formula.tagString !== null) trees.push('  tag: ' + formula.tagString);
    collectWarnings(formula, references);
    for (const warning of formula.warnings) diagnostic(errors, formula, warning, true);
    warningCount += formula.warnings.length;
    for (const line of result.overfull) errors.push(`${heading}: line ${line.number} is overfull (width ${line.width} > ${params.width})`);
    overfullCount += result.overfull.length;
  }
  boxReport.push(`summary: boxes=${boxCount} max_depth=${maxDepth}`);
  for (const kind of Array.from(kinds.keys()).sort()) boxReport.push(`  ${kind}: ${kinds.get(kind)}`);
  errors.push(`formulas=${formulas.length} rendered=${valid} errors=${formulas.length - valid} warnings=${warningCount} overfull=${overfullCount}`);
  fs.mkdirSync('output', { recursive: true });
  fs.writeFileSync('output/rendered.txt', rendered.join('\n\n') + '\n', 'ascii');
  fs.writeFileSync('output/boxes.txt', boxReport.join('\n') + '\n', 'ascii');
  fs.writeFileSync('output/trees.txt', trees.join('\n') + '\n', 'ascii');
  fs.writeFileSync('output/errors.txt', errors.join('\n') + '\n', 'ascii');
}

function main() {
  const params = Object.fromEntries(inputLines('params.txt').map(line => {
    const [name, value] = line.split(' '); return [name, Number(value)];
  }));
  const formulas = parseFormulas(inputLines('formulas.txt'));
  const references = equationReferences(formulas);
  writeReports(formulas, params, references);
}

main();

'use strict';

const { FormulaError } = require('./lexer');
const TERMINATORS = new Set(['}', '&', 'newline', 'right', 'end', 'eof']);
const ARGUMENTS = new Set(['identifier', 'number', 'symbol', 'command', 'text', 'eqref', '{', 'frac', 'binom', 'overset', 'underset', 'sqrt', 'accent']);
const emptyRow = () => ({ kind: 'row', elements: [] });
const collapse = elements => elements.length === 1 ? elements[0] : { kind: 'row', elements };

function checkBraces(tokens) {
  const stack = [];
  for (const token of tokens) {
    if (token.kind === '{') stack.push(token.column);
    else if (token.kind === '}') {
      if (stack.length === 0) throw new FormulaError(token.column, 'unmatched }');
      stack.pop();
    }
  }
  if (stack.length) throw new FormulaError(stack[stack.length - 1], 'unclosed {');
}

class Parser {
  constructor(tokens) { this.tokens = tokens; this.index = 0; this.tag = null; this.label = null; }
  peek() { return this.tokens[Math.min(this.index, this.tokens.length - 1)]; }
  read() { const token = this.peek(); this.index++; return token; }
  unexpected(token) {
    const messages = { right: 'unexpected \\right', end: 'unexpected \\end', '&': 'misplaced &', newline: 'misplaced \\\\' };
    throw new FormulaError(token.column, messages[token.kind]);
  }
  parse() {
    checkBraces(this.tokens);
    const elements = this.elementList(true);
    if (this.peek().kind !== 'eof') this.unexpected(this.peek());
    return { elements, tag: this.tag, label: this.label };
  }
  elementList(top = false, rootIndex = false) {
    const elements = [];
    while (true) {
      const next = this.peek();
      if (TERMINATORS.has(next.kind) || (rootIndex && next.kind === 'symbol' && next.value === ']')) return elements;
      if (next.kind === 'tag' || next.kind === 'label') {
        if (!top) throw new FormulaError(next.column, 'misplaced \\' + next.kind);
        if (this[next.kind] !== null) throw new FormulaError(next.column, 'duplicate \\' + next.kind);
        this[next.kind] = this.read(); continue;
      }
      elements.push(this.element());
    }
  }
  element() {
    const base = this.peek().kind === '^' || this.peek().kind === '_' ? emptyRow() : this.nucleus();
    let sub = null, sup = null;
    while (this.peek().kind === '^' || this.peek().kind === '_') {
      const token = this.read();
      if (token.kind === '^') {
        if (sup !== null) throw new FormulaError(token.column, 'double superscript');
        sup = this.argument('^');
      } else {
        if (sub !== null) throw new FormulaError(token.column, 'double subscript');
        sub = this.argument('_');
      }
    }
    return sub === null && sup === null ? base : { kind: 'script', base, sub, sup };
  }
  argument(name) {
    if (!ARGUMENTS.has(this.peek().kind)) throw new FormulaError(this.peek().column, 'missing argument for ' + name);
    return this.nucleus();
  }
  delimiter() {
    const token = this.read();
    if (token.kind === 'symbol' && ['(', ')', '[', ']', '|', '.'].includes(token.value)) return token.value;
    if (token.kind === 'command' && ['\\{', '\\}'].includes(token.value)) return token.value;
    throw new FormulaError(token.column, 'invalid delimiter');
  }
  nucleus() {
    const token = this.read(), kind = token.kind;
    if (['identifier', 'number', 'symbol', 'command', 'text', 'eqref'].includes(kind)) {
      return { kind: 'atom', atom: kind === 'eqref' ? 'reference' : kind, value: token.value, column: token.column };
    }
    if (kind === '{') {
      const elements = this.elementList();
      if (this.peek().kind !== '}') this.unexpected(this.peek());
      this.read(); return collapse(elements);
    }
    if (['frac', 'binom', 'overset', 'underset'].includes(kind)) {
      const first = this.argument('\\' + kind), second = this.argument('\\' + kind);
      return kind === 'overset' || kind === 'underset' ? { kind, placed: first, base: second } : { kind, first, second };
    }
    if (kind === 'sqrt') {
      let index = null;
      if (this.peek().kind === 'symbol' && this.peek().value === '[') {
        const opening = this.read(), elements = this.elementList(false, true);
        if (this.peek().kind !== 'symbol' || this.peek().value !== ']') throw new FormulaError(opening.column, 'missing ]');
        this.read(); index = collapse(elements);
      }
      const body = this.argument('\\sqrt');
      return index === null ? { kind: 'sqrt', body } : { kind: 'root', index, body };
    }
    if (kind === 'accent') return { kind: 'accent', name: token.value, body: this.argument('\\' + token.value) };
    if (kind === 'left') {
      const left = this.delimiter(), elements = this.elementList();
      if (this.peek().kind !== 'right') throw new FormulaError(token.column, 'missing \\right');
      const rightColumn = this.read().column, right = this.delimiter();
      return { kind: 'delim', left, right, body: collapse(elements), rightColumn };
    }
    return this.matrix(token);
  }
  matrix(begin) {
    const rows = [[]];
    while (true) {
      rows[rows.length - 1].push(collapse(this.elementList()));
      const token = this.read();
      if (token.kind === '&') continue;
      if (token.kind === 'newline') { rows.push([]); continue; }
      if (token.kind !== 'end') throw new FormulaError(begin.column, 'missing \\end');
      if (token.value !== begin.value) throw new FormulaError(token.column, 'mismatched \\end');
      break;
    }
    const last = rows[rows.length - 1];
    if (rows.length >= 2 && last.length === 1 && last[0].kind === 'row' && last[0].elements.length === 0) rows.pop();
    const columns = Math.max(...rows.map(row => row.length));
    for (const row of rows) while (row.length < columns) row.push(emptyRow());
    return { kind: 'matrix', environment: begin.value, rows };
  }
}

module.exports = { Parser, checkBraces, collapse };
